-- Craft Stash on PostgreSQL 13+. The same tables as sqlite.sql: timestamps are 'YYYY-MM-DD HH:MM:SS' UTC text, JSON
-- columns are text, quantities are double precision. Runs as one script on every start, so everything is idempotent.

-- Case-insensitive text, like SQLite's COLLATE NOCASE (usernames, storage places, and ORDER BY ... COLLATE NOCASE).
CREATE COLLATION IF NOT EXISTS nocase (provider = icu, locale = 'und-u-ks-level2', deterministic = false);

CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT COLLATE nocase UNIQUE NOT NULL, pw TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, theme TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pools(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, name TEXT NOT NULL, craft TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS types(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pool_id BIGINT NOT NULL REFERENCES pools ON DELETE CASCADE, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'pcs', fields TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type_id BIGINT NOT NULL REFERENCES types ON DELETE CASCADE, name TEXT NOT NULL, colour TEXT NOT NULL DEFAULT '', hex TEXT NOT NULL DEFAULT '', subtype TEXT NOT NULL DEFAULT '', qty DOUBLE PRECISION NOT NULL DEFAULT 0, price DOUBLE PRECISION, low_at DOUBLE PRECISION, location TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', extra TEXT NOT NULL DEFAULT '{}', photo TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS projects(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', notes TEXT NOT NULL DEFAULT '', created TEXT NOT NULL DEFAULT '', updated TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS assignments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects ON DELETE CASCADE, item_id BIGINT NOT NULL REFERENCES items ON DELETE CASCADE, qty DOUBLE PRECISION NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, used DOUBLE PRECISION NOT NULL DEFAULT 0, UNIQUE(project_id, item_id));
CREATE TABLE IF NOT EXISTS files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects ON DELETE CASCADE, name TEXT NOT NULL, stored TEXT NOT NULL, size BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pool_shares(pool_id BIGINT NOT NULL REFERENCES pools ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, can_edit INTEGER NOT NULL DEFAULT 0, UNIQUE(pool_id, user_id));
CREATE TABLE IF NOT EXISTS project_shares(project_id BIGINT NOT NULL REFERENCES projects ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, UNIQUE(project_id, user_id));
CREATE TABLE IF NOT EXISTS steps(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects ON DELETE CASCADE, pos INTEGER NOT NULL, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ts TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'), user_id BIGINT REFERENCES users ON DELETE SET NULL, pool_id BIGINT NOT NULL REFERENCES pools ON DELETE CASCADE, item_id BIGINT, kind TEXT NOT NULL, text TEXT NOT NULL, delta DOUBLE PRECISION, undone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS step_photos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, step_id BIGINT NOT NULL REFERENCES steps ON DELETE CASCADE, stored TEXT NOT NULL, size BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS item_places(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item_id BIGINT NOT NULL REFERENCES items ON DELETE CASCADE, place TEXT COLLATE nocase NOT NULL, qty DOUBLE PRECISION NOT NULL, UNIQUE(item_id, place));
CREATE TABLE IF NOT EXISTS api_tokens(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, name TEXT NOT NULL, hash TEXT UNIQUE NOT NULL, can_write INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'), last_used TEXT);

CREATE INDEX IF NOT EXISTS ix_types_pool ON types(pool_id);
CREATE INDEX IF NOT EXISTS ix_items_type ON items(type_id);
CREATE INDEX IF NOT EXISTS ix_assign_project ON assignments(project_id);
CREATE INDEX IF NOT EXISTS ix_assign_item ON assignments(item_id);
CREATE INDEX IF NOT EXISTS ix_files_project ON files(project_id);
CREATE INDEX IF NOT EXISTS ix_steps_project ON steps(project_id);
CREATE INDEX IF NOT EXISTS ix_step_photos_step ON step_photos(step_id);
CREATE INDEX IF NOT EXISTS ix_activity_pool ON activity(pool_id, id);
CREATE INDEX IF NOT EXISTS ix_pool_shares_user ON pool_shares(user_id);
CREATE INDEX IF NOT EXISTS ix_project_shares_user ON project_shares(user_id);
CREATE TABLE IF NOT EXISTS project_tags(project_id BIGINT NOT NULL REFERENCES projects ON DELETE CASCADE, tag TEXT NOT NULL, UNIQUE(project_id, tag));
CREATE INDEX IF NOT EXISTS ix_project_tags_tag ON project_tags(tag);
CREATE INDEX IF NOT EXISTS ix_pools_user ON pools(user_id);
CREATE INDEX IF NOT EXISTS ix_projects_user ON projects(user_id);
CREATE INDEX IF NOT EXISTS ix_activity_user ON activity(user_id);
CREATE INDEX IF NOT EXISTS ix_activity_ts ON activity(ts);
CREATE INDEX IF NOT EXISTS ix_api_tokens_user ON api_tokens(user_id);
CREATE TABLE IF NOT EXISTS user_identities(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, issuer TEXT NOT NULL, subject TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', created TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'), UNIQUE(issuer, subject));
CREATE INDEX IF NOT EXISTS ix_user_identities_user ON user_identities(user_id);
CREATE TABLE IF NOT EXISTS wishes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, name TEXT NOT NULL, colour TEXT NOT NULL DEFAULT '', hex TEXT NOT NULL DEFAULT '', qty DOUBLE PRECISION NOT NULL DEFAULT 1, unit TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', photo TEXT NOT NULL DEFAULT '', type_id BIGINT REFERENCES types ON DELETE SET NULL, item_id BIGINT REFERENCES items ON DELETE SET NULL, project_id BIGINT REFERENCES projects ON DELETE SET NULL, got INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL DEFAULT '', got_at TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ix_wishes_user ON wishes(user_id);
CREATE INDEX IF NOT EXISTS ix_wishes_type ON wishes(type_id);
CREATE INDEX IF NOT EXISTS ix_wishes_item ON wishes(item_id);
CREATE INDEX IF NOT EXISTS ix_wishes_project ON wishes(project_id);
CREATE TABLE IF NOT EXISTS wish_sightings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, wish_id BIGINT NOT NULL REFERENCES wishes ON DELETE CASCADE, shop TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '', price DOUBLE PRECISION, seen TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ix_wish_sightings_wish ON wish_sightings(wish_id);

-- The app keeps item_places within items.qty itself (adjust_stock, save_item); this is the backstop for every other
-- way qty changes, the same rule as SQLite's places_fit trigger.
CREATE OR REPLACE FUNCTION places_fit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE held DOUBLE PRECISION;
BEGIN
  SELECT COALESCE(SUM(qty), 0) INTO held FROM item_places WHERE item_id = NEW.id;
  IF NEW.qty < held THEN
    UPDATE item_places SET qty = qty * NEW.qty / held WHERE item_id = NEW.id;
    DELETE FROM item_places WHERE item_id = NEW.id AND qty < 1e-9;
  END IF;
  RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS places_fit ON items;
CREATE TRIGGER places_fit AFTER UPDATE OF qty ON items FOR EACH ROW EXECUTE FUNCTION places_fit();

CREATE OR REPLACE VIEW access AS
  SELECT id AS pool_id, user_id, 1 AS can_edit, 1 AS is_owner FROM pools
  UNION ALL SELECT pool_id, user_id, can_edit, 0 FROM pool_shares;
CREATE OR REPLACE VIEW stock AS
  SELECT i.*, t.name AS tname, t.unit, t.pool_id, p.name AS pname, p.user_id,
         i.qty - COALESCE((SELECT SUM(a.qty) FROM assignments a WHERE a.item_id = i.id AND a.consumed = 0
                     AND a.project_id NOT IN (SELECT id FROM projects WHERE status = 'template')), 0) AS free
  FROM items i JOIN types t ON t.id = i.type_id JOIN pools p ON p.id = t.pool_id;
